import iconNames from "./iconNames.json" with { type: "json" };
import { AppError } from "./errors.js";

/** Bundled ingredient icon names, sorted. Generated by `pnpm icons:manifest`. */
export const ICON_NAMES: readonly string[] = iconNames;

const iconSet = new Set<string>(iconNames);

/**
 * Normalize an ingredient `imageUrl`: null/empty = automatic icon; an http(s)
 * URL = custom image; otherwise it must name a bundled icon.
 */
export function normalizeImageUrl(raw: string | null | undefined): string | null {
  if (raw === null || raw === undefined) return null;
  const value = raw.trim();
  if (value === "") return null;

  try {
    const url = new URL(value);
    if (url.protocol === "http:" || url.protocol === "https:") return value;
  } catch {
    // Not a URL; try an icon name below.
  }

  const name = value.toLowerCase();
  if (iconSet.has(name)) return name;

  throw new AppError(
    "validation",
    `Unknown ingredient icon "${value}". Use null for automatic, a bundled icon name (see list_icons), or an http(s) URL.`,
    { imageUrl: value },
  );
}
